        assert.equal(manual.query.type, 'pr', 'manual request lives on the PR');
        assert.ok((manual.query.labels || []).indexOf('agent:rework') !== -1);
        assert.ok(!manual.query.prMachineAuthor, 'manual rework is NOT author-gated');
