if (rule.localAction === 'fail_validation' || sweepFailure) {
    // Validation CI went red: unarm, tell the PR, and — MACHINE PRs
    // only — requeue the machine loop by re-arming agent:rework (the
    // linked issue carries it; an unlinked machine PR gets the
    // PR-anchored arm). Owner rule 2026-09-21: auto-REWORK is
    // machine-author-ONLY. Accounts other than the machine login are
    // guests: they get review + validation and no rework arm — a
    // guest "fixes #<n>" body must not arm rework on a machine ticket.
    // gh-757 (live fa#1286, 2026-10-06, vendor vabhzw17eg2qu4m9-bit):
    // REVERTS the 2026-10-04 guest validation-red arm — that
    // directive spent an AI rework leg on a vendor PR (the very burn
    // the 2026-09-21 rule exists to prevent). Guest recovery = the
    // #1179 validation_failed park + the #633 RESET probe (the guest
    // pushes a fix, the park clears, validation re-runs);
    // rework-on-label still honours a MANUAL agent:rework label from
    // a human on any PR.
    try {
        // gh-755 (owner directive 2026-10-05): CANCELLED is never
        // a verdict. The query matched `checks: red` on a rollup
        // snapshot — before any verdict action (unarm, report,
        // guest park, rework arm), re-read the head's check
        // rollup: if the red dissolves into cancelled-only (no
        // FAILURE/TIMED_OUT on the LATEST run of any
        // non-bookkeeping context), this is NO verdict — skip and
        // wait for the rerun-cancelled-checks remedy to re-stamp
        // the contexts. The ai_validating arm STAYS on: the rerun
        // re-stamps under it and the verdict rules consume the
        // fresh word next tick. Re-work legs burned on
        // cancelled-only heads (live dmtools-agents #752/#753,
        // kicker sm-liveness + docs-freshness after the 15m
        // window) are exactly the token burn this directive
        // forbids.
        var fvHead = (ticket.pr && ticket.pr.headSha) || ticket.headSha;
        if (fvHead && !headHasRealFailure(effectiveRepoInfo, fvHead)) {
            console.log('  ⏭️  ' + key + ' red is cancelled-only — no verdict (gh-755):' +
                        ' skipping the fail path, waiting on the rerun-cancelled-checks remedy');
            continue;
        }
        try {
            githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).removeLabel(ticket.prNumber, 'ai_validating');
        } catch (e3) { /* absent label is fine */ }
        var machineAuthor = machineAuthorModule.resolveMachineAuthor(RUN_JOB_PARAMS, effectiveConfig);
        // gh-728: the knob is a LIST — a direct single-login string
        // compare here parked bot PRs (github-actions[bot] ≠
        // 'ai-teammate') as guests forever (live fa PR #1249).
        var isMachinePr = machineAuthorModule.isMachineAuthored(
            ticket, machineAuthor, effectiveRepoInfo.owner);
        // gh-806 AC1: consult the rework in-flight latch before ANY
        // rework arm — a leg already flying for this (pr, head) owns
        // the fix; re-arming stacked 9 arms / 8 dead legs (fa #1428).
        // Guests never reach an arm branch — no consult for them.
        var reworkLatched = isMachinePr
            ? consultReworkLatch(key, ticket, effectiveRepoInfo).latched
            : false;
        var linked = null;
        if (isMachinePr) {
            try {
                var prRaw = github_get_pr({
                    workspace: effectiveRepoInfo.owner,
                    repository: effectiveRepoInfo.repo,
                    pullRequestId: ticket.prNumber
                });
                var prObj = typeof prRaw === 'string' ? JSON.parse(prRaw) : (prRaw || {});
                var m = /(?:closes|fixes|resolves)\s+#(\d+)/i.exec(String(prObj.body || ''));
                if (m) linked = parseInt(m[1], 10);
            } catch (e4) { console.warn('  ⚠️ linked-issue lookup failed: ' + (e4.message || e4)); }
            // Fallback (live: fa pr-750 — body said "Fixes the Play Store
            // rejection (gh-746)", no closing keyword): machine PRs carry
            // the issue in the branch name (ai/gh-<n>). Guest branches
            // get nothing — issue RESOLUTION stays machine-only, and
            // gh-757: a guest red never arms rework anywhere (park only).
            if (!linked && ticket.branch) {
                var bm = /(?:^|\/)gh-(\d+)$/i.exec(String(ticket.branch));
                if (bm) linked = parseInt(bm[1], 10);
            }
        }
        // pr_approved is STICKY (owner rule 2026-09: no re-review
        // after the first approval — review tokens are the budget).
        // Validation red post-approval re-arms rework only; the
        // fixed head re-validates via validate-armed and merges —
        // the reviewer never re-fires. Pre-review red also skips
        // this block: no approval exists to unarm. (Supersedes the
        // fa pr-750 unarm fix: the validate↔fail burn it patched is
        // now closed by the latch itself.)
        // Failed-run link (owner 2026-10-01): the report says CI
        // went red — link the exact red run(s) on this head so the
        // reader (a guest especially) never hunts the runs tab.
        // Graceful '' on any miss (no head SHA, empty run list,
        // tool error): the report posts without the link and
        // NOTHING else in this action changes.
        // ONE github_list_workflow_runs fetch feeds BOTH the
        // failed-run link line (below) and the gh-832
        // consecutive-red streak — the list is the durable per-head
        // verdict record; no markers, no second fetch.
        var failCiWf = rule.ciWorkflow ||
            ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml';
        var failRunList = dispatchedValidationRuns(effectiveRepoInfo, failCiWf);
        var failedRunsLine = failedRunLinksFromList(failRunList,
            (ticket.pr && ticket.pr.headSha) || ticket.headSha);
        // ── COMPOSITION #703 (review #703 blocker): the caps live on
        // THIS red, in one report — the red-head marker bounds the
        // RE-VALIDATION loop (any PR: a head with redHeadCap recorded
        // reds is never re-armed — only a genuinely NEW head re-enters
        // validation) and the empty-lap cap bounds the MACHINE rework
        // loop (same-head red = a lap that pushed nothing — at
        // emptyLapMax the machine arm is withheld and the owner is
        // escalated to). #701's guest-rework cap is gone with the
        // guest arm itself (gh-757: auto-rework is machine-only).
        //
        // One comment read per fail (review #703 💡): all marker
        // kinds — red-head counts, empty laps — parse from a SINGLE
        // github_get_pr_comments payload.
        var failMarks = failMarkerState(effectiveRepoInfo, ticket.prNumber);
        // Red-head history (owner directive 2026-10-04: red yields
        // the slot): append the per-head counter marker to the
        // report — the validate_pr arm side re-reads these markers
        // and refuses to re-arm a head that already went red
        // redHeadCap times (default 3). Recording is UNCONDITIONAL
        // (the skip alone is toggleable …

/**
 * Red-verdict convergence (gh-832) — repeated red validation verdicts on an
 * approved head must CONVERGE, never loop dispatch→red→unarm→rearm forever.
 *
 * Live fa PR #1453 (2026-10-10 00:20–08:00Z): 12 dispatch→red→unarm→rearm
 * cycles on an approved head, 5 concluded FAILUREs in a row (the PTY/CLI
 * shard 0/3 flake), zero merges fleet-wide for 3.5h. The existing guards
 * could not stop it: the empty-lap cap and the redHeadSkip arm-side skip
 * are per-head-SHA marker counters — every head refresh resets them, and
 * even when they fire their terminal state is a SILENT log line (no park,
 * no comment). Machine-authored PRs were never parked at all (gh-757 parks
 * guests only) — so a fleet-wide flake in main looped the whole window,
 * and the quarantine PR (#1470) could not merge through it.
 *
 * This module is the pure half of the fix: the consecutive-red streak is
 * DERIVED from the head's own dispatched run history (the durable per-head
 * record, same github_list_workflow_runs list the fail path already fetches
 * for its failed-run link line) — no new markers, no new state carriers:
 *
 *   streakFromRuns(runs, headSha) — trailing count of consecutive concluded
 *      red verdict runs on THIS head (workflow_dispatch only, newest-first).
 *      A 'success' run breaks the streak (gh-832 AC2: a green verdict resets
 *      the counter); 'cancelled' runs are skipped (gh-755 — CANCELLED is
 *      never a verdict, it neither counts nor resets); any other concluded
 *      conclusion (failure/timed_out/…) counts as a red verdict word (sweep
 *      parity). A head change resets the streak by construction — the count
 *      is filtered to the exact head SHA (gh-832 AC2).
 *   parkCapOf(jobParams) — jobParams.redHeadParkCap (default 2): at N
 *      consecutive reds on the unchanged head the fail path parks
 *      validation_failed + a report naming the failing job(s). 0 or
 *      'false' disables the park (deployment escape hatch; the red-head
 *      marker audit trail and the 3-red arm-side skip are unaffected).
 *
 * Pure functions, no tool globals — smAgent wires the transport, tests
 * inject nothing. CommonJS module like every other js/ module. GraalJS
 * rules apply: var + plain functions only.
 */

'use strict';

/**
 * The head's consecutive concluded-red verdict count, derived from the
 * dispatched-run list (REST shape: [{ event, head_sha, status, conclusion,
 * created_at, updated_at }, …], any order — sorted here newest-first).
 *
 * Walk newest-first over THIS head's workflow_dispatch runs:
 *   completed + conclusion 'success'      → streak ends (green reset, AC2)
 *   completed + conclusion 'cancelled'    → skipped (gh-755: never a verdict)
 *   completed + anything else             → red verdict — streak++
 *   any other status (queued/…)           → ignored (not a verdict)
 * Runs of other heads, other events, and null entries never participate.
 * A null/failed fetch degrades to 0 (fail OPEN: no park on a degraded read —
 * the red-head marker skip still bounds the re-arm arm at 3).
 */
function streakFromRuns(runs, headSha) {
    if (!headSha || !Array.isArray(runs)) return 0;
    var mine = runs.filter(function (r) {
        return r && r.event === 'workflow_dispatch' &&
            r.head_sha === headSha && r.status === 'completed';
    });
    mine.sort(function (a, b) {
        return Date.parse(b.updated_at || b.created_at || 0) -
               Date.parse(a.updated_at || a.created_at || 0);
    });
    var streak = 0;
    for (var i = 0; i < mine.length; i++) {
        var c = mine[i].conclusion ? String(mine[i].conclusion) : null;
        if (!c || c === 'cancelled') continue;      // gh-755 — no verdict word
        if (c === 'success') break;                 // AC2 — green resets
        streak++;
    }
    return streak;
}

/**
 * The convergence park threshold: how many consecutive red verdicts on an
 * unchanged head park validation_failed. Default 2 (gh-832 AC1: the SECOND
 * consecutive red parks — no third dispatch). jobParams.redHeadParkCap tunes
 * it per deployment; 0 / negative / 'false' disable the park entirely.
 */
function parkCapOf(jobParams) {
    if (String((jobParams || {}).redHeadParkCap) === 'false') return 0;
    var n = (jobParams || {}).redHeadParkCap;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n <= 0) return 2;
    return Math.floor(n);
}

/**
 * The park decision at fail time: the CURRENT red is already in the fetched
 * run list, so the streak includes it — park when streak >= cap.
 */
function shouldPark(streak, cap) {
    return cap > 0 && streak >= cap;
}

module.exports = {
    streakFromRuns: streakFromRuns,
    parkCapOf: parkCapOf,
    shouldPark: shouldPark
};

/**
 * Rework in-flight latch (gh-806) — one arming decision per (pr-number,
 * head-sha).
 *
 * Live fa PR #1428 (2026-10-09 04:01–05:04Z): the SM tick logged 9 rework
 * arming decisions for ONE push; 8 legs died silently (dispatch accepted,
 * run never materialized) because rework idempotency lived only in the
 * `agent:rework` label lifecycle and the dispatch-time in-flight-run guards
 * — neither keys the ARMING decision on the PR head. This module is that
 * missing latch:
 *
 *   AC1  while a rework leg for (pr, head) is latched, the tick's armer
 *        logs `⏭️ … rework already in flight for (pr, head)` and dispatches
 *        nothing — `isActive` is the gate every rework arming path consults.
 *   AC2  the latch clears when the leg terminates: a CONCLUDED leg run
 *        (`ai-teammate.yml` workflow) on the latched head that concluded at
 *        or after the arm — success or failure — clears it; a NEW head is a
 *        new key and re-arms normally by construction.
 *   AC3  a latch older than DEFAULT_STALE_MS (45 min) with NO matching
 *        active run is stale and cleared — a leg that never produced a run
 *        is re-armable after a bounded timeout, no human needed.
 *   AC4  lives in the thread fetchers (githubHelpers/scm providers), not
 *        here — resolved threads are filtered before the agent sees them.
 *
 * Persistence: the tick keeps ONE map in memory per pass and rides it into
 * the factory-state snapshot (`state.reworkInFlight`, js/factoryState.js),
 * which the next tick loads back — fa-state.json on the `factory-data`
 * branch is the store, exactly like tick.processed.
 *
 * Pure functions, no tool globals — smAgent wires the transport, tests
 * inject nothing. CommonJS module like every other js/ module. GraalJS
 * rules apply: var + plain functions only.
 */

'use strict';

// gh-806 AC3: N = 45 minutes. A rework leg that produced no run within this
// window is treated as silently dead and the (pr, head) becomes re-armable.
var DEFAULT_STALE_MS = 45 * 60 * 1000;

// The rework/review leg workflow (smAgent dispatches it via workflowRef={branch}).
// Configurable per call so a deployment that renames the workflow stays exact.
var DEFAULT_LEG_WORKFLOW = 'ai-teammate.yml';

var ACTIVE_RUN_STATES = ['queued', 'in_progress', 'waiting', 'pending', 'requested'];

function latchKey(prNumber, headSha) {
    if (prNumber === null || prNumber === undefined || prNumber === '') return null;
    if (!headSha || typeof headSha !== 'string') return null;
    return 'pr-' + prNumber + '@' + headSha;
}

/**
 * Epoch-ms from an epoch number OR an ISO string; null when unparsable.
 */
function toMs(value) {
    if (value === null || value === undefined || value === '') return null;
    if (typeof value === 'number') return isNaN(value) ? null : value;
    var parsed = Date.parse(String(value));
    return isNaN(parsed) ? null : parsed;
}

function nowMsOf(opts) {
    var ms = toMs(opts && opts.now);
    return ms === null ? Date.now() : ms;
}

function staleMsOf(opts) {
    var ms = toMs(opts && opts.staleMs);
    return (ms === null || ms <= 0) ? DEFAULT_STALE_MS : ms;
}

function workflowFileOf(opts) {
    var wf = opts && opts.workflowFile;
    return (wf && typeof wf === 'string') ? wf : DEFAULT_LEG_WORKFLOW;
}

/**
 * Sanitize a persisted latch map (the snapshot's reworkInFlight). Keeps only
 * well-formed entries — 'pr-<N>@<head>' keys with a non-empty head string and
 * an `at` field (the timestamp may itself be unparsable; isActive then fails
 * CLOSED to stale so a corrupt stamp can never latch forever). Anything else
 * is dropped: the latch must never wedge the armer on snapshot drift.
 */
function normalizeMap(raw) {
    var map = {};
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return map;
    Object.keys(raw).forEach(function (key) {
        var entry = raw[key];
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return;
        if (typeof key !== 'string' || key.indexOf('@') === -1) return;
        if (!entry.head || typeof entry.head !== 'string') return;
        if (!entry.at) return;
        map[key] = { head: entry.head, at: entry.at };
        if (entry.by) map[key].by = String(entry.by);
    });
    return map;
}

/**
 * Record an arming decision for (prNumber, headSha) at `atIso` (default now).
 * No head sha → nothing to key on → no-op (legacy items keep re-arming).
 * Mutates and returns `map` so callers can chain on their own instance.
 */
function arm(map, prNumber, headSha, atIso, by) {
    var key = latchKey(prNumber, headSha);
    if (!key) return map;
    var target = (map && typeof map === 'object') ? map : {};
    target[key] = {
        head: headSha,
        at: atIso || new Date().toISOString()
    };
    if (by) target[key].by = String(by);
    return target;
}

/**
 * Remove the latch for (prNumber, headSha). No-op on unknown keys.
 */
function clear(map, prNumber, headSha) {
    var key = latchKey(prNumber, headSha);
    if (key && map && typeof map === 'object') delete map[key];
    return map;
}

function entryFor(map, prNumber, headSha) {
    var key = latchKey(prNumber, headSha);
    if (!key || !map || typeof map !== 'object') return null;
    var entry = map[key];
    return (entry && typeof entry === 'object') ? entry : null;
}

/**
 * True when the run belongs to the rework/review LEG workflow (path ends
 * with '/<workflowFile>') — the same shape hasActiveLegRun matches in
 * smAgent. Validation CI or kicker runs on the same head must never
 * influence the latch.
 */
function isLegRun(run, workflowFile) {
    if (!run) return false;
    var suffix = '/' + String(workflowFile || DEFAULT_LEG_WORKFLOW);
    var path = String(run.path || '');
    return path.length >= suffix.length &&
        path.slice(path.length - suffix.length) === suffix;
}

function isActiveStatus(status) {
