        var p = (cfg.params && cfg.params.jobParams) || {};
        assert.equal(p.validationConcurrency, 3, '3-wide validation window');
        assert.ok(p.validationConcurrency >= 1 && p.validationConcurrency <= 5,
            'inside the gh-837 clamp');
