                    { number: 1315, labels: [], draft: true,         // draft
                      user: { login: 'ai-teammate' }, head: { ref: 'wip' }, body: '' },
                    { number: 1316, labels: [], draft: false,        // checks 'none' — validate-fresh's shape
                      user: { login: 'ai-teammate' }, head: { ref: 'ai/gh-1315' }, body: 'Closes #1315' }
                ];
