        },
        localAction: 'arm_rework',
        redHeadGated: true,
        limit: 1,
        id: 'rework-on-red-gate-unlatched'
    };

    function devItem(n, head, extra) {
        var it = { key: 'pr-' + n, labels: [], issueNumber: null, prNumber: n, draft: false,
                   headSha: head };
