    }, { 100: ['ai_developed'], 101: ['ai_developed'] });

    var items = srcMod.query({
        source: 'github',
        query: {
            type: 'issue',
            labels: ['ai_developed'],
            mergeStateLatch: { CLEAN: ['ai_developed'] }
