                pr: { number: 413, body: 'Closes #412', head: { sha: HEAD } },
                prComments: []
            }
        }));
        sm.action({ jobParams: { owner: 'epam', repo: 'dmtools-dart',
            machineAuthor: 'ai-teammate', rules: [RULE] } });

